#include <assert.h>

class FEMenu;
class FEMenuSystem;
class entity;
class MultiLineString;
class TextString;

struct stringx { unsigned int value; };
struct color32 { unsigned int value; };

class FEMenuEntry
{
public:
	int entry_num;
	FEMenuEntry* next;
	FEMenuEntry* previous;
	FEMenu* menu;

protected:
	bool highlight;
	bool disabled;
	entity* ent;
	color32 high_ent_color;
	color32 norm_ent_color;
	MultiLineString* text;

private:
	float highlight_intensity;
	float highlight_timer;
	int disabled_alpha;
	color32 special_color;
	color32 special_color_high;
	bool has_special_color;
	bool no_flash;
	float special_scale;
	float special_scale_high;
	bool has_special_scale;

public:
	FEMenuEntry* up;
	FEMenuEntry* down;
	FEMenuEntry* left;
	FEMenuEntry* right;

	virtual ~FEMenuEntry();
	virtual void Load() {}
	virtual void OnSelect() {}
	virtual void Highlight(bool h = true, bool anim=true);
	virtual void Disable(bool d = true);
	virtual bool GetDisable() { return disabled; }
};

enum {
	FEMENU_SCROLLING			= 0x001,
	FEMENU_WRAP					= 0x002,
	FEMENU_DONT_SKIP_DISABLED	= 0x040,
	FEMENU_DONT_SHOW_DISABLED	= 0x400,
};

class FEMenu
{
public:
	int center_x;
	int center_y;
	int num_entries;
	int dy;
	int half;
	int menu_num;
	bool init;
	stringx font_filename;
	color32 color;
	color32 color_high;
	color32 color_high_alt;
	float scale;
	float scale_high;
	int max_vis_entries;
	int flags;

	FEMenuEntry* entries;
	FEMenuEntry* first_vis_entry;
	FEMenuEntry* last_vis_entry;
	FEMenuEntry* highlighted;
	FEMenuSystem* system;
	FEMenu* back;
	int back_num;

protected:
	FEMenu *submenus;
	FEMenu *active;
	FEMenu *parent;
	TextString *helpText;
	int helpFlags;

public:
	FEMenu* next_sub;

	virtual ~FEMenu();
	virtual void setBack(FEMenu* b, int bn=1) { back = b; back_num = bn; }
	virtual void setHigh(FEMenuEntry* menu, bool anim=true);
	virtual void setVis(FEMenuEntry* first);

protected:
	virtual void Next();
};

void FEMenu::Next()
{
	assert(highlighted);
	if(!(flags & FEMENU_WRAP))
	{
		if(highlighted == entries->previous) return;
		FEMenuEntry* tmp = highlighted->next;

		// loop through until end of list or hit a not-disabled entry.
		// if we hit the bottom of the list first, then there's nowhere else to go
		while(tmp && tmp->GetDisable()) tmp = tmp->next;
		if(!tmp) return;
	}
	if((flags & FEMENU_SCROLLING) && highlighted == last_vis_entry)
	{
		FEMenuEntry* first = first_vis_entry->next;
		if(!first) first = entries;
		if(flags & FEMENU_DONT_SHOW_DISABLED)
		{
			while(first->GetDisable() && first != highlighted)
			{
				first = first->next;
				if(!first) first = entries;
			}
		}
		setVis(first);
	}

	FEMenuEntry* tmp = highlighted->next;
	if(!tmp) tmp = entries;
	if(!(flags & FEMENU_DONT_SKIP_DISABLED))
	{
		while(tmp->GetDisable() && tmp != highlighted)
		{
			tmp = tmp->next;
			if(!tmp) tmp = entries;
		}
	}
	setHigh(tmp);
}
